Let's explore fundamental operations on strings in JavaScript:

```js
let greeting = "Hello";
let name = "World";

// Concatenation
let message = greeting + ", " + name + "!"; // "Hello, World!"

// String Length
console.log(message.length); // 13

// Accessing characters
console.log(message[0]); // 'H'

// Checking substring
console.log(message.includes("World")); // true

// Escape characters
let quote = "He said, \"I love coding.\"";
console.log(quote); // He said, "I love coding."
```

These operations form the foundation for any string task you'll do, from formatting display messages to validating input.

Strings often require formatting, such as making all characters uppercase or trimming unnecessary whitespace.

```js
let messy = "   JavaScript Is Cool   ";

// Convert to uppercase
console.log(messy.toUpperCase()); // '   JAVASCRIPT IS COOL   '

// Convert to lowercase
console.log(messy.toLowerCase()); // '   javascript is cool   '

// Trim whitespace from both ends
console.log(messy.trim()); // 'JavaScript Is Cool'

// Trim only start or end
console.log(messy.trimStart()); // 'JavaScript Is Cool   '
console.log(messy.trimEnd());   // '   JavaScript Is Cool'
```

Case transformation is often used in normalization (e.g., to compare emails). Trimming is critical for input sanitization and UI formatting.

Splitting and joining strings are used in tokenization, CSV parsing, building dynamic queries, etc.

```js
let sentence = "The quick brown fox";

// Split into array of words
let words = sentence.split(" ");
console.log(words); // ['The', 'quick', 'brown', 'fox']

// Join array back into string with a different delimiter
let joined = words.join("-");
console.log(joined); // 'The-quick-brown-fox'
```

You can split by any delimiter (e.g., comma, space, or even an empty string). This is useful when breaking data into components and reassembling it with control.

A palindrome is a string that reads the same forward and backward.

```js
function isPalindrome(str) {
  let clean = str.toLowerCase().replace(/[^a-z0-9]/g, '');
  return clean === clean.split('').reverse().join('');
}

console.log(isPalindrome("Racecar")); // true
console.log(isPalindrome("hello"));   // false
```

We sanitize the string by removing non-alphanumeric characters and normalizing case. Then we check if the reverse matches the original.

Two strings are anagrams if they contain the same characters in different orders.

```js
function isAnagram(a, b) {
  let normalize = str => str.toLowerCase().replace(/[^a-z0-9]/g, '').split('').sort().join('');
  return normalize(a) === normalize(b);
}

console.log(isAnagram("listen", "silent")); // true
console.log(isAnagram("hello", "world"));   // false
```

We normalize both strings by sorting their characters and then comparing them.

Let's implement a simple version of the pattern matching algorithm:

```js
function naiveSearch(text, pattern) {
  let positions = [];
  for (let i = 0; i <= text.length - pattern.length; i++) {
    let match = true;
    for (let j = 0; j < pattern.length; j++) {
      if (text[i + j] !== pattern[j]) {
        match = false;
        break;
      }
    }
    if (match) positions.push(i);
  }
  return positions;
}

console.log(naiveSearch("ababcabcab", "abc")); // [2, 5]
```

This is a brute-force approach that checks every position. It's not efficient but forms the base for understanding better algorithms.
